const BASE = 'https://spotyloader.com'

const headers = {
  'user-agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36',
  'accept': '*/*',
  'content-type': 'application/json',
  'origin': BASE,
  'referer': BASE + '/',
}

function detectType(url) {
  const u = url.trim()
  if (/^spotify:(track|playlist|album|artist):[A-Za-z0-9]+$/i.test(u)) {
    const m = u.match(/^spotify:(track|playlist|album|artist):/i)
    return m[1].toLowerCase()
  }
  try {
    const parsed = new URL(u)
    const host = parsed.hostname.toLowerCase()
    if (host !== 'open.spotify.com' && host !== 'spotify.com' && !host.endsWith('.spotify.com')) return null
    const m = parsed.pathname.match(/^\/(?:intl-[a-z-]+\/)?(track|playlist|album|artist)\/([A-Za-z0-9]+)/i)
    return m ? m[1].toLowerCase() : null
  } catch {
    return null
  }
}

function fmtDuration(ms) {
  const s = Math.round(ms / 1000)
  const m = Math.floor(s / 60)
  return m + ':' + String(s % 60).padStart(2, '0')
}

function checkError(status, data) {
  if (data?.error) throw new Error(data.error)
  if (data?.message && data.success === false) throw new Error(data.message)
  if (status >= 400) throw new Error(`HTTP ${status}`)
}

async function apiGet(path) {
  const r = await fetch(BASE + path, { headers, cache: 'no-store' })
  const data = await r.json()
  checkError(r.status, data)
  return data
}

async function apiPost(path, body) {
  const r = await fetch(BASE + path, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
    cache: 'no-store',
  })
  const data = await r.json()
  checkError(r.status, data)
  return data
}

async function getInfo(url) {
  const type = detectType(url)
  if (!type) throw new Error('Invalid Spotify URL')
  const encoded = encodeURIComponent(url.trim())
  if (type === 'track') {
    return { type, data: (await apiGet(`/api/spotify/info?url=${encoded}`)).post || (await apiGet(`/api/spotify/info?url=${encoded}`)) }
  }
  if (type === 'artist') {
    return { type, data: (await apiGet(`/api/spotify/artist?url=${encoded}`)).post }
  }
  if (type === 'playlist' || type === 'album') {
    return { type, data: (await apiPost(`/api/spotify/${type}`, { url: url.trim() })).post }
  }
  throw new Error('Unsupported type: ' + type)
}

async function convertTrack(url, format = 'mp3') {
  const r = await apiPost('/api/spotify/track', { url: url.trim(), format })
  if (!r.jobId) throw new Error('Failed to start conversion')
  return r.jobId
}

async function pollStatus(jobId, maxAttempts = 60, interval = 3000) {
  for (let i = 0; i < maxAttempts; i++) {
    await new Promise(r => setTimeout(r, interval))
    const r = await apiGet(`/api/spotify/track/status/${jobId}`)
    if (r.status === 'ready' && r.downloadLink) return r
    if (r.status === 'error') throw new Error(r.error || 'Conversion failed')
    if (r.status !== 'pending' && r.status !== 'processing') throw new Error('Unknown status: ' + r.status)
  }
  throw new Error('Timeout: conversion took too long')
}

async function downloadTrack(url, format = 'mp3') {
  const jobId = await convertTrack(url, format)
  const result = await pollStatus(jobId)
  return {
    status: true,
    name: result.post?.name || 'unknown',
    artist: result.post?.artist || 'unknown',
    album: result.post?.album || '',
    format: result.post?.format || format,
    download_url: result.downloadLink,
    duration: result.post?.duration_ms ? fmtDuration(result.post.duration_ms) : '',
    image: result.post?.image || '',
  }
}

async function searchTracks(query, limit = 10) {
  const encoded = encodeURIComponent(query)
  const data = await apiGet(`/api/spotify/search?q=${encoded}&limit=${limit}`)
  return (data.items || []).map(t => ({
    name: t.name,
    artist: t.artist,
    url: t.url,
    duration: fmtDuration(t.duration_ms),
    image: t.image || '',
    source: t.source,
  }))
}

function showUsage() {
  console.log(`
Usage:
  node spotyloader.js <spotify-url>              Download a track
  node spotyloader.js <spotify-url> <format>     Download with format (mp3/m4a/flac)
  node spotyloader.js search <query>             Search for tracks
  node spotyloader.js search <query> <limit>     Search with result limit

Supported URL types:
  - Track:  https://open.spotify.com/track/...
  - Playlist: https://open.spotify.com/playlist/...
  - Album:  https://open.spotify.com/album/...
  - Artist: https://open.spotify.com/artist/...

Examples:
  node spotyloader.js https://open.spotify.com/track/1BxfuPKGuaTgP7aM0Bbdwr
  node spotyloader.js https://open.spotify.com/track/1BxfuPKGuaTgP7aM0Bbdwr flac
  node spotyloader.js search "bohemian rhapsody"
  node spotyloader.js search "queen" 5
`)
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length === 0) { showUsage(); return }

  try {
    if (args[0].toLowerCase() === 'search') {
      if (args.length < 2) { console.log(JSON.stringify({ status: false, message: 'Search requires a query' }, null, 2)); return }
      const query = args[1]
      const limit = parseInt(args[2]) || 10
      console.log(`Searching for "${query}" (${limit} results)...`)
      const results = await searchTracks(query, limit)
      if (results.length === 0) {
        console.log(JSON.stringify({ status: false, message: 'No results found' }, null, 2))
        return
      }
      console.log(JSON.stringify(results, null, 2))
      return
    }

    const type = detectType(args[0])
    if (!type) { console.log(JSON.stringify({ status: false, message: 'Invalid Spotify URL' }, null, 2)); return }

    if (type === 'track') {
      const format = args[1] || 'mp3'
      if (!['mp3', 'm4a', 'flac'].includes(format)) {
        console.log(JSON.stringify({ status: false, message: 'Format must be mp3, m4a, or flac' }, null, 2))
        return
      }
      console.log(`Converting track to ${format.toUpperCase()}...`)
      const result = await downloadTrack(args[0], format)
      console.log(JSON.stringify(result, null, 2))
      return
    }

    const info = await getInfo(args[0])
    console.log(JSON.stringify(info.data, null, 2))
  } catch (err) {
    console.log(JSON.stringify({ status: false, message: err.message }, null, 2))
  }
}

main()
